import{_ as a,o as i,c as e,ai as t}from"./chunks/framework.Duywnu3E.js";const k=JSON.parse('{"title":"4. Настройте службу сетевого времени на базе сервиса chrony на маршрутизаторе ISP:","description":"","frontmatter":{},"headers":[],"relativePath":"module2/task2-4.md","filePath":"module2/task2-4.md"}'),n={name:"module2/task2-4.md"};function l(p,s,r,h,c,o){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="_4-настроите-службу-сетевого-времени-на-базе-сервиса-chrony-на-маршрутизаторе-isp" tabindex="-1">4. Настройте службу сетевого времени на базе сервиса chrony на маршрутизаторе ISP: <a class="header-anchor" href="#_4-настроите-службу-сетевого-времени-на-базе-сервиса-chrony-на-маршрутизаторе-isp" aria-label="Permalink to “4. Настройте службу сетевого времени на базе сервиса chrony на маршрутизаторе ISP:”">​</a></h1><details class="details custom-block"><summary>Задания</summary><p>• Вышестоящий сервер ntp на маршрутизаторе ISP - на выбор участника</p><p>• Стратум сервера - 5</p><p>• В качестве клиентов ntp настройте: HQ-SRV, HQ-CLI, BR-RTR, BR-SRV.</p></details><h2 id="_1-настроика-сервера" tabindex="-1">1. Настройка сервера <a class="header-anchor" href="#_1-настроика-сервера" aria-label="Permalink to “1. Настройка сервера”">​</a></h2><p>Открываем файл /etc/chrony.conf на машине ISP</p><p>скачиваем</p><div class="language-Shell"><button title="Copy Code" class="copy"></button><span class="lang">Shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chrony</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span></span></code></pre></div><p>прописываем</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sed -i &#39;s/^pool/#pool/&#39; /etc/chrony.conf</span></span></code></pre></div><p>переходим в файл <code>/etc/chrony.conf</code></p><p>Меняет строчку local stratum 10 на local stratum 5</p><p>После чего добавляем строчки:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>server ntp0.ntp-servers.net iburst prefer minstratum 4</span></span>
<span class="line"><span>allow 0.0.0.0/0</span></span></code></pre></div><p>Перезагружаем chronyd</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl restart chronyd</span></span></code></pre></div><h2 id="_2-настроика-машин" tabindex="-1">2. Настройка машин <a class="header-anchor" href="#_2-настроика-машин" aria-label="Permalink to “2. Настройка машин”">​</a></h2><p>прописываем на всех машинах</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt-get update &amp;&amp; apt-get install chrony -y</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sed -i &#39;s/^pool/#pool/&#39; /etc/chrony.conf</span></span>
<span class="line"><span>echo &quot;server 172.16.1.1 iburst&quot; &gt;&gt; /etc/chrony.conf</span></span>
<span class="line"><span>systemctl restart chronyd</span></span></code></pre></div><p>Для машин BR-RTR BR-SRV сервер будет 172.16.2.1 Для HQ-SRV HQ-CLI HQ-RTR сервер будет 172.16.1.1 соответственно</p><h2 id="_3-проверка" tabindex="-1">3. Проверка <a class="header-anchor" href="#_3-проверка" aria-label="Permalink to “3. Проверка”">​</a></h2><p>На клиенте при команде chronyc sources должно выводить ip адрес ISP</p><p>На сервере при команде chronyc clients должно выводить ip адреса всех обоих RTR</p>`,21)])])}const g=a(n,[["render",l]]);export{k as __pageData,g as default};
